func (f *Factory) ClearBaseXPEventMods() {
	f.baseXPEventMods = nil
}

func (f *Factory) AddBaseXPEventMod(mods ...XPEventMod) {
	f.baseXPEventMods = append(f.baseXPEventMods, mods...)
}
